import {
  ChangeDetectionStrategy,
  Component,
  Input,
  Output,
  EventEmitter,
  OnInit,
  ChangeDetectorRef,
  Inject
} from '@angular/core';
import { BetValidatedContext, DrawGameBetSlipService } from '@honoregaming/betslip';
import { EMPTY } from 'rxjs';
import { catchError, finalize, takeUntil } from 'rxjs/operators';
import {
  BetPlacedPromotionMode,
  globalConfiguration,
  OperatorConfiguration,
  operatorConfigurationToken
} from '@honoregaming/configuration';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import { TelemetryService } from '@honoregaming/customer-core';
import { InstantGameService } from '@honoregaming/events';
import { BetCategoryType, InstantGame, InstantGameProvider } from '@honoregaming/types';
import { MessageService } from '@honoregaming/ui';
import { BetSlipSimulateComponent } from 'projects/core/hg-betslip/src/lib/components/bet-slip-simulate/bet-slip-simulate.component';

type EnrichedInstantGame = InstantGame & { computedUrl: string };

@Component({
  selector: 'hg-bet-validated',
  templateUrl: './bet-validated.component.html',
  styleUrls: ['./bet-validated.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetValidatedComponent extends DestroySubject implements OnInit {
  @Input() context!: BetValidatedContext;
  @Input() isGettingBetCode?: boolean;

  @Output() close = new EventEmitter<{ keepSelection: boolean; isSimulate: boolean }>();
  @Output() getBetCode = new EventEmitter<number>();

  public BetCategoryType = BetCategoryType;
  public BetPlacedPromotionMode = BetPlacedPromotionMode;

  betPlacedPromotionMode?: BetPlacedPromotionMode;
  promotedInstantGames?: EnrichedInstantGame[];
  assetsPath: string = '';
  canReplayDrawGame: boolean = false;

  private readonly instantGamesBetCategoryPath: string =
    this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  private readonly baseAssetsPath: string = this.operatorConfiguration.instantGamesConfiguration.insaGamesAssetsPath;
  private readonly maxPromotedGames: number = 4;

  constructor(
    private readonly messageService: MessageService,
    public readonly instantGameService: InstantGameService,
    public readonly cdRef: ChangeDetectorRef,
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private drawGameBetSlipService: DrawGameBetSlipService,
    private readonly telemetryService: TelemetryService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit(): void {
    this.initAssetsPath();
    this.initBetPlacedPromotion();
    this.initReplayDrawGame();
  }

  get hasBetCodeButton(): boolean {
    if (this.context.hideBetCode) return false;

    return this.isSportsFixedOdds || this.isDrawGameWithBetCode;
  }

  get displayMaxPayout(): boolean {
    return this.context.maxPayout && this.context.betCategoryType !== BetCategoryType.SportsPool;
  }

  private get isSportsFixedOdds(): boolean {
    return this.context.betCategoryType === BetCategoryType.SportsFixedOdds;
  }

  private get isDrawGameWithBetCode(): boolean {
    return (
      this.context.betCategoryType === BetCategoryType.DrawGame &&
      this.operatorConfiguration.betCodeConfiguration.activeForDrawGame
    );
  }

  onClose(keepSelection: boolean, isSimulate: boolean = false): void {
    this.close.emit({ keepSelection, isSimulate });
  }

  onGetBetCode(e: Event): void {
    e.stopPropagation();
    this.getBetCode.emit(this.context.betSystemId);
  }

  openSimulateModal(e: Event): void {
    e.stopPropagation();
    this.messageService.sendComponentMessage(
      BetSlipSimulateComponent,
      {},
      { canBeDismissed: false, displayClose: false }
    );
  }

  handleClick(e: Event): void {
    e.stopPropagation();
  }

  keepSelection(): void {
    this.telemetryService.trackEvent('bet_slip_keep_my_selection');
    this.onClose(true);
  }

  private initAssetsPath(): void {
    this.assetsPath = this.extractBaseUrl(globalConfiguration.assetsPath);
  }

  private initBetPlacedPromotion(): void {
    this.betPlacedPromotionMode = this.operatorConfiguration.onlineConfiguration?.betPlacedPopInPromotion;

    if (this.betPlacedPromotionMode === BetPlacedPromotionMode.Casino) {
      this.getPromotedInstantGames();
    }
  }

  private initReplayDrawGame(): void {
    this.canReplayDrawGame =
      this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection;
  }

  private extractBaseUrl(url: string): string {
    const match: RegExpExecArray = /^(https?:\/\/[^\/]+)/.exec(url);
    return match ? match[0] : '';
  }

  private getPromotedInstantGames(): void {
    this.instantGameService
      .getPromotedInstantGames()
      .pipe(
        takeUntil(this.destroy$),
        catchError(() => {
          this.promotedInstantGames = [];
          return EMPTY;
        }),
        finalize(() => this.cdRef.markForCheck())
      )
      .subscribe((gamesList: InstantGame[]) => this.handlePromotedInstantGames(gamesList));
  }

  private handlePromotedInstantGames(gamesList: InstantGame[]): void {
    const countInsaGames: number = this.operatorConfiguration.onlineConfiguration?.popInPromotionInsaGamesCount || 0;

    const selectedGames: InstantGame[] = this.selectPromotedGames(gamesList, countInsaGames);
    const shuffledGames: InstantGame[] = this.shuffleInstantGames(selectedGames);

    this.promotedInstantGames = shuffledGames
      .map(game => this.enrichGameWithUrls(game))
      .filter((game): game is EnrichedInstantGame => !!game);
  }

  private selectPromotedGames(gamesList: InstantGame[], countInsaGames: number): InstantGame[] {
    const insaGames: InstantGame[] = [];
    const otherGames: InstantGame[] = [];

    for (const game of gamesList) {
      if (game.provider === InstantGameProvider.InsaGames) {
        insaGames.push(game);
      } else {
        otherGames.push(game);
      }
    }

    const selectedInsaGames: InstantGame[] =
      countInsaGames > 0 ? this.shuffleInstantGames(insaGames, countInsaGames) : [];

    const selectedOtherGames: InstantGame[] =
      countInsaGames < this.maxPromotedGames
        ? this.shuffleInstantGames(otherGames, this.maxPromotedGames - countInsaGames)
        : [];

    return [...selectedInsaGames, ...selectedOtherGames];
  }

  private enrichGameWithUrls(game: InstantGame): EnrichedInstantGame | undefined {
    const computedUrl: string = `/${this.instantGamesBetCategoryPath}/${game.url}`;

    switch (game.provider) {
      case InstantGameProvider.InsaGames:
        return {
          ...game,
          computedUrl,
          imageUrl: game.imageUrl || `${this.baseAssetsPath}${game.name.toLowerCase()}/thumbnail.png`
        };

      case InstantGameProvider.GameTech:
        return {
          ...game,
          computedUrl,
          imageUrl: `${this.assetsPath}/instant-game-providers/${game.imageUrl}`
        };

      case InstantGameProvider.EveryMatrix:
      case InstantGameProvider.AviatorLlc:
        return { ...game, computedUrl };

      case InstantGameProvider.BoomingGames:
        return {
          ...game,
          computedUrl: `/${this.instantGamesBetCategoryPath}/` + game.url,
          imageUrl: game.imageUrl
        };

      default:
        return undefined;
    }
  }

  private shuffleInstantGames(gamesList: InstantGame[], count?: number): InstantGame[] {
    const shuffled: InstantGame[] = [...gamesList];

    for (let i = shuffled.length - 1; i > 0; i--) {
      const j: number = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }

    return count === undefined ? shuffled : shuffled.slice(0, count);
  }

  replay(): void {
    this.drawGameBetSlipService.replay(
      this.operatorConfiguration?.drawGameConfiguration?.allowsCustomerToReplayLastDrawGameSelection
    );
  }
}
